import React from "react";
import "./MyEvents.css";
import headerImage from "../../../assets/MyEventsHeader.png"; // correct relative import
import TedTalk from "../../../assets/TedTalk.png";
import GetTogether from "../../../assets/getTogether.jpg";

const MyEvents = () => {
  const events = [
    { id: 1, name: "TED talk", date: "2025-10-20", location: "Hall building", image: require("../../../assets/TedTalk.png") },
    { id: 2, name: "Get together", date: "2025-11-05", location: "ER building", image: require("../../../assets/getTogether.jpg") }
  ];

  return (
    <div className="my-events-container">
      <div className="header-image">
        <h1>My Events</h1>
      </div>

      <div className="events-list-section">
        {events.length === 0 ? (
          <p>You haven’t purchased any events yet.</p>
        ) : (
          <ul className="event-list">
            {events.map((event) => (
              <li key={event.id} className="event-item">
                <img src={event.image} alt={event.title} className="event-image" />
                <div className="event-details">
                  <h3>{event.title}</h3>
                  <p>{event.date}</p>
                </div>
              </li>
            ))}
          </ul>
        )}
      </div>
  </div>
  );
};

export default MyEvents;
